package finance.config;
import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ConfigPresetResourceTest {
 @Test void presetsUseKnownBoundedKeysAndNeverDisableAdminPermission()throws Exception{for(String name:List.of("minecraft_first","casual_server","legacy_finance")){String text=Files.readString(Path.of("config-presets",name+".toml"));assertTrue(text.contains("[gameplay]"),name);assertTrue(text.contains("adminConsoleRequiresPermission = true"),name);assertTrue(text.contains("worldgenEnabled = false"),name);assertFalse(text.contains("adminConsoleRequiresPermission = false"),name);Map<String,Double> values=numbers(text);assertBetween(values,"terminalInteractionDistance",1,32);assertBetween(values,"maxCargoUnits",1,16384);assertBetween(values,"demandDeadlineDays",1,30);assertBetween(values,"rewardBasisPoints",5000,20000);assertBetween(values,"maximumTargetDistance",128,16384);assertBetween(values,"deadlineDays",1,30);assertBetween(values,"reward",1,100000);}}
 private static Map<String,Double> numbers(String text){Map<String,Double> result=new HashMap<>();for(String line:text.lines().toList()){String clean=line.split("#",2)[0].trim();if(!clean.contains("=")||clean.startsWith("["))continue;String[]parts=clean.split("=",2);try{result.put(parts[0].trim(),Double.parseDouble(parts[1].trim()));}catch(NumberFormatException ignored){}}return result;}
 private static void assertBetween(Map<String,Double> values,String key,double min,double max){assertTrue(values.containsKey(key),key);assertTrue(values.get(key)>=min&&values.get(key)<=max,key+"="+values.get(key));}
}
